#!/bin/sh
inventory_menu(){ while :; do c=$(ui_menu Inventory "Report: $REPORT_DIR/inventory.txt" rescan 'Rescan system' summary 'Show summary' full 'Show full report' packages 'List installed packages' configs 'Find managed configuration blocks' export 'Copy report to chosen path') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in rescan) scan_system; ui_msg Inventory 'Scan complete.';; summary) ui_text Summary "$(head -n 40 "$REPORT_DIR/inventory.txt")";; full) ui_text Inventory "$(cat "$REPORT_DIR/inventory.txt")";; packages) list_packages;; configs) ui_text Managed "$(grep -R '^# >>> ish-aok-config:' "$CURRENT_HOME" /etc 2>/dev/null|head -n 200)";; export) p=$(ui_input Export 'Destination:' "$CURRENT_HOME/ish-aok-inventory.txt") || continue; cp "$REPORT_DIR/inventory.txt" "$p";; esac; done; }
list_packages(){ case $PKG_MGR in apt) dpkg-query -W -f='${binary:Package}\t${Version}\n';; apk) apk info -vv;; pacman) pacman -Q;; dnf|yum) rpm -qa;; xbps) xbps-query -l;; emerge) qlist -Iv 2>/dev/null;; *) echo unavailable;; esac >"$TMP_DIR/packages" 2>&1; ui_text Packages "$(cat "$TMP_DIR/packages")"; }
